        replaceItem(G.l.PlayerData, (num((num((num(t.v.myPlayer) - 1)) * num(G.v.JUMPER))) + 14), (num(item(G.l.PlayerData, (num((num((num(t.v.myPlayer) - 1)) * num(G.v.JUMPER))) + 14))) - 50));
        replaceItem(G.l.PlayerData, (num((num((num(t.v.myPlayer) - 1)) * num(G.v.JUMPER))) + 1), (num((num((num(t.v.myPlayer) - 1)) * num(G.v.JUMPER))) + num((num((num(item(G.l.PlayerData, (num((num((num(t.v.myPlayer) - 1)) * num(G.v.JUMPER))) + 1))) / Math.abs(num(item(G.l.PlayerData, (num((num((num(t.v.myPlayer) - 1)) * num(G.v.JUMPER))) + 1)))))) * 20))));
        replaceItem(G.l.PlayerData, (num((num((num(t.v.myPlayer) - 1)) * num(G.v.JUMPER))) + 9), "40");
        replaceItem(G.l.PlayerData, (num((num((num(t.v.myPlayer) - 1)) * num(G.v.JUMPER))) + 10), "2");
